def _execute_ga_check_part_03(argv: list[str], _split_state):
    if _split_state['args'].report_out is not None:
        write_ga_readiness_report(_split_state['report'], _split_state['args'].report_out)
    if _split_state['args'].json:
        print(json.dumps(_split_state['report'], ensure_ascii=False, indent=2))
    else:
        print_ga_readiness_report(_split_state['report'])
    if _split_state['report'].get('status') == 'blocked':
        raise SystemExit(1)
    return (True, None)
    return (False, None)

def _execute_ga_check(argv: list[str]) -> None:
    _split_state: JsonDocument = {}
    _split_result = _execute_ga_check_part_01(argv, _split_state)
    if _split_result[0]:
        return _split_result[1]
    _split_result = _execute_ga_check_part_02(argv, _split_state)
    if _split_result[0]:
        return _split_result[1]
    _split_result = _execute_ga_check_part_03(argv, _split_state)
    if _split_result[0]:
        return _split_result[1]

def handle_ga_check(argv: list[str]) -> None:
    _execute_ga_check(argv)

__all__ = ('_execute_ga_check', 'handle_ga_check')
